#!/usr/bin/env python3
# pushoverKachel. Schreibt dashboard.py und die neue Datei pushover_push.py.
# Basis: dashboard.py nach Trotzdem-klonen (Marker cloneForce). ntfy_push.py bleibt.
# Kein pip, kein apt, kein Pushover-Versand.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
NTFY = ("b535f9f2c404626de89bd0637595354840084255179500ec272a0caecd48e452", 5831)
FIXED = {
    "prepper_sdr.py": "9b2f565c65db2090bd819fe84fe8dd7d6ca2e68d23acf29ff9934ad7d867ea62",
    "pinneberg_rolle.py": "2fb1af4ccd333e6596721fd641cdf84f86e6d3b8014fe95386e1aa77cf23f49d",
    "pinneberg_rx.py": "835b9697eda8aac521823e6e4becf655782cdda412f7c2147f36183d2b621b96",
}
PREFIX = {
    "ups_manager.py": ("6658f0ef31f060f4", 64197),
    "lage_pages.py": ("f593e87b9dd8c46a", 216599),
    "prepper_docs.py": ("eaaf54b50c03b92d", None),
}

def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    pair = raw["dash"][0]
    return base64.b64decode(pair["old"]), base64.b64decode(pair["new"]), base64.b64decode(raw["file"])

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def basis_ok(name, data: bytes) -> bool:
    if name == "ntfy_push.py":
        return sha(data) == NTFY[0] and len(data) == NTFY[1]
    if name in FIXED:
        return sha(data) == FIXED[name]
    head, size = PREFIX[name]
    if not sha(data).startswith(head):
        return False
    return size is None or len(data) == size

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def schreiben(path: Path, data: bytes, mode: int):
    tmp = path.with_name("." + path.name + ".tmp-psh")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-psh-*"))
    bak = path.with_name(path.name + ".bak-psh-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def apply_dir(ordner: Path, dry: bool, kein: bool) -> int:
    old, neu, datei = load()
    namen = ["ntfy_push.py"] + list(FIXED) + list(PREFIX) + ["dashboard.py"]
    for name in namen:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    blobs = {name: (ordner / name).read_bytes() for name in namen}
    for name in ["ntfy_push.py"] + list(FIXED) + list(PREFIX):
        if not basis_ok(name, blobs[name]):
            print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
            return 2
    dash = blobs["dashboard.py"]
    print("dashboard.py sha16 %s" % sha(dash)[:16])
    ziel = ordner / "pushover_push.py"
    if ziel.is_symlink():
        print("STOP: pushover_push.py ist ein Verweis")
        return 2
    vorhanden = ziel.read_bytes() if ziel.is_file() else None
    if vorhanden is not None and vorhanden != datei:
        print("STOP: pushover_push.py ist nicht die neue Datei")
        return 2
    fertig = b"pushoverKachel" in dash and dash.count(neu) == 1 and vorhanden == datei
    if fertig:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if b"cloneForce" not in dash or b"stimmePiper" not in dash:
        print("STOP: dashboard.py ist nicht der Stand nach Trotzdem-klonen")
        return 2
    dash_neu = dash
    if dash.count(neu) != 1:
        if dash.count(old) != 1 or b"pushoverKachel" in dash:
            print("STOP: dashboard.py Stelle unbekannt")
            return 2
        vor = dash
        dash_neu = dash.replace(old, neu, 1)
        if dash_neu.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            print("STOP: dashboard.py wuerde ausserhalb der Stelle geaendert")
            return 2
    if b"pushoverKachel" not in dash_neu or b"api.pushover.net" in dash_neu.split(b"pushover_push")[0][-200:]:
        print("STOP: pushoverKachel unvollstaendig")
        return 2
    try:
        compile(dash_neu, "dashboard.py", "exec")
        compile(datei, "pushover_push.py", "exec")
    except SyntaxError as exc:
        print("STOP: Syntax %s" % exc.lineno)
        return 2
    frei, meldung = fenster()
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    try:
        if dash_neu != dash:
            sichern(ordner / "dashboard.py", dash)
            mode = (ordner / "dashboard.py").stat().st_mode & 0o777
            schreiben(ordner / "dashboard.py", dash_neu, mode)
        if vorhanden != datei:
            schreiben(ziel, datei, 0o644)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    for name in ["ntfy_push.py"] + list(FIXED) + list(PREFIX):
        if (ordner / name).read_bytes() != blobs[name]:
            print("STOP: %s wurde angefasst" % name)
            return 3
    print("geschrieben. dashboard.py Kachel PUSHOVER, neue Datei pushover_push.py. ntfy_push.py unveraendert.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    import subprocess
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    old, neu, datei = load()
    blob = b"# FREMD-PSH\n" + old
    assert blob.replace(old, neu, 1).count(b"# FREMD-PSH") == 1
    assert b"pushoverKachel" in neu and b"cloneForce" not in old[:20]
    compile(datei, "pushover_push.py", "exec")
    assert b"priority=2" not in datei.split(b"def post")[1].split(b"def ")[0] or b"priority=2" in datei
    assert fenster(datetime(2026, 11, 12, 12, 10))[0] and fenster(datetime(2026, 11, 12, 12, 5))[0]
    assert not fenster(datetime(2026, 11, 12, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 12, 12, 0))[0]
    assert not fenster(datetime(2026, 11, 12, 12, 4))[0]
    assert basis_ok("ntfy_push.py", b"x") is False
    assert basis_ok("lage_pages.py", b"LAGE") is False
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="psh-apply-"))
    namen = ["ntfy_push.py"] + list(FIXED) + list(PREFIX) + ["dashboard.py"]
    for name in namen:
        (ordner / name).write_bytes(b"UNBERUEHRT-" + name.encode())
    vorher = {name: (ordner / name).read_bytes() for name in namen}
    rc = apply_dir(ordner, False, True)
    assert rc == 2 and {name: (ordner / name).read_bytes() for name in namen} == vorher
    assert not (ordner / "pushover_push.py").exists()
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD = {"dash": [{"old": "", "new": ""}], "file": ""}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
